import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents half to even: 124.5 -> 124', () => {
  assert.equal(roundCents(124.5), 124);
});

test('roundCents half to even: 125.5 -> 126', () => {
  assert.equal(roundCents(125.5), 126);
});

test('roundCents: 2.4 -> 2', () => {
  assert.equal(roundCents(2.4), 2);
});

test('roundCents: -0.5 -> 0', () => {
  assert.equal(roundCents(-0.5), 0);
});

test('formatEuros: 123456 -> "€1,234.56"', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
});

test('formatEuros: -5 -> "-€0.05"', () => {
  assert.equal(formatEuros(-5), '-€0.05');
});

test('formatEuros: 0 -> "€0.00"', () => {
  assert.equal(formatEuros(0), '€0.00');
});

test('parseEuros: "12" -> 1200', () => {
  const result = parseEuros('12');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1200);
});

test('parseEuros: "12.5" -> 1250', () => {
  const result = parseEuros('12.5');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1250);
});

test('parseEuros: "1,234.56" -> 123456', () => {
  const result = parseEuros('1,234.56');
  assert.equal(result.ok, true);
  assert.equal(result.value, 123456);
});

test('RATES has EUR, USD, GBP', () => {
  assert('EUR' in RATES);
  assert('USD' in RATES);
  assert('GBP' in RATES);
});

test('RATES.EUR is 1', () => {
  assert.equal(RATES.EUR, 1);
});

test('RATES.USD is 1.085', () => {
  assert.equal(RATES.USD, 1.085);
});

test('RATES.GBP is 0.8425', () => {
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 100);
});

test('convert EUR cents to USD cents', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  const expected = Math.round(10000 * 1.085);
  assert.equal(result.value, expected);
});

test('convert EUR cents to GBP cents', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  const expected = Math.round(10000 * 0.8425);
  assert.equal(result.value, expected);
});

test('convert returns UNKNOWN_CURRENCY for invalid currency', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert with 0 cents', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert negative cents EUR to USD', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  const expected = Math.round(-10000 * 1.085);
  assert.equal(result.value, expected);
});

test('formatMoney EUR with €', () => {
  const result = formatMoney(123456, 'EUR');
  assert.equal(result, '€1,234.56');
});

test('formatMoney USD with $', () => {
  const result = formatMoney(100000, 'USD');
  assert(result.startsWith('$'));
  assert(result.includes(','));
});

test('formatMoney GBP with £', () => {
  const result = formatMoney(100000, 'GBP');
  assert(result.startsWith('£'));
  assert(result.includes(','));
});

test('formatMoney with zero cents', () => {
  const result = formatMoney(0, 'USD');
  assert.equal(result, '$0.00');
});

test('formatMoney with negative cents', () => {
  const result = formatMoney(-10000, 'EUR');
  assert(result.startsWith('-'));
  assert(result.includes('€'));
});

test('formatMoney returns empty string for invalid currency', () => {
  const result = formatMoney(10000, 'JPY');
  assert.equal(result, '');
});

test('formatMoney formats 2 decimal places', () => {
  const result = formatMoney(123456, 'USD');
  assert(result.endsWith('.56'));
});

test('formatMoney has thousand separator', () => {
  const result = formatMoney(1234567, 'EUR');
  assert(result.includes(','));
});

test('formatMoney for 5 cents EUR', () => {
  const result = formatMoney(5, 'EUR');
  assert.equal(result, '€0.05');
});

test('convert produces integer cents', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  assert(Number.isInteger(result.value));
});

test('formatMoney uses correct rates', () => {
  const eurCents = 10000;
  const usdResult = convert(eurCents, 'USD');
  const gbpResult = convert(eurCents, 'GBP');

  const usdFormatted = formatMoney(eurCents, 'USD');
  const gbpFormatted = formatMoney(eurCents, 'GBP');

  assert(usdFormatted.startsWith('$'));
  assert(gbpFormatted.startsWith('£'));
  assert(usdFormatted !== gbpFormatted);
});

test('convert 1 EUR to USD rounds correctly', () => {
  const result = convert(100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, Math.round(100 * 1.085));
});

test('formatMoney negative EUR', () => {
  const result = formatMoney(-100, 'EUR');
  assert.equal(result, '-€1.00');
});

test('formatMoney negative USD', () => {
  const result = formatMoney(-100, 'USD');
  assert.equal(result, '-$1.00');
});

test('formatMoney negative GBP', () => {
  const result = formatMoney(-100, 'GBP');
  assert.equal(result, '-£1.00');
});

test('convert with different integer amounts', () => {
  const amounts = [1, 10, 100, 1000, 10000, 100000];
  amounts.forEach((amount) => {
    const usdResult = convert(amount, 'USD');
    const gbpResult = convert(amount, 'GBP');
    assert(usdResult.ok);
    assert(gbpResult.ok);
    assert(Number.isInteger(usdResult.value));
    assert(Number.isInteger(gbpResult.value));
  });
});

test('formatMoney large amounts', () => {
  const result = formatMoney(123456789, 'EUR');
  assert(result.includes('€'));
  assert(result.includes(','));
});

test('convert preserves precision', () => {
  const result1 = convert(10000, 'USD');
  const result2 = convert(10000, 'USD');
  assert.equal(result1.value, result2.value);
});

test('convert case-sensitive', () => {
  const result = convert(10000, 'usd');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

